#!/usr/bin/env bash
# Round 396 PERF-13c-ii-b claims (L29 + L56). Run from the loop root. CLAIMS_STORE overrides the store path.
L=$(pwd); S=${CLAIMS_STORE:-/home/runner/czaba-project/store}; C=$S/app/contexts/ArrangementContext.tsx; P=$S/app/lib/arrangement/preview.client.ts; CO=$S/app/lib/arrangement/collection.ts; TC=$S/app/lib/arrangement/__tests__/collection.test.ts; T=$S/app/lib/arrangement/__tests__/library-preview-stream.test.tsx; PS=$S/perf/studio-lab-resources.perf.spec.ts; PB=$S/perf/budgets.resources.json; D=$S/docs/implementation/2026/quarter-IV/252-perf-library-preview-stream.md; D8=$S/docs/implementation/2026/quarter-IV/248-perf-decoded-buffer-cache.md; LP=$S/app/components/arrangement/ArrangementLibraryPreview.tsx
echo "K1 $(python3 -I -c "import json;g=json.load(open('gates/gate-round-395.json'));print(g['status'],g['commit'][:7])")"
echo "K2 $(git -C $S rev-parse --short HEAD 2>/dev/null) $(git -C $S status --short --untracked-files=all | wc -l)"
echo "K3 $(cd $S && sha256sum -c $L/b-round-318/protected-sha256.txt 2>/dev/null | grep -c ': OK$')"
echo "K4 $(cd $S && sha256sum -c $L/b-round-395/r396-frozen-sha256.txt 2>/dev/null | grep -vc ': OK$') $(wc -l < b-round-395/r396-frozen-sha256.txt)"
echo "K5 $(python3 -I -c "import json;d=json.load(open('regression-last.json'));print(d['date'],d['round'])")"
echo "K6 $(curl -s -o /dev/null -w '%{http_code}' --max-time 30 http://127.0.0.1:5173/studio-lab)"
echo "K7 $(python3 -I -c "import json;c=json.load(open('c-round-395.json'));print(c['taskStatus'],len(c['bugs']),c['browserVerified'],c['realVerified'])")"
echo "K8 adapter preview-url $(grep -c 'previewUrl: (source) => stemUrls.get(source.id) ?? null,' $CO) stem-map $(grep -c 'const stemUrls = new Map<string, string>();' $CO) load-uses-map $(grep -c 'const url = stemUrls.get(source.id);' $CO)"
echo "K9 player cross-origin $(grep -c "element.crossOrigin = 'anonymous';" $P) seek-restart $(grep -c 'active.restartArmedStall();' $P) removes $(grep -c 'removeEventListener(' $P) try $(grep -c 'try {' $P) stall-const $(grep -c 'export const LIBRARY_PREVIEW_STREAM_STALL_MS = 8000;' $P) same-url $(grep -c "active?.kind === 'stream' && active.url === url" $P)"
echo "K10 provider preview-url-call $(grep -c '(collection.previewUrl?.(source) ?? null)' $C) fallback-scoped $(grep -c '!(fallback?.collection === collection && fallback.sourceIds.has(sourceId))' $C) stream-call $(grep -c 'playLibraryPreviewStream' $C) cache-in-stream-branch $(awk '/if \(source && streamUrl !== null\) \{/,/^        return;$/' $C | grep -cE 'decodedBuffers\.(set|setPinned)|stemCache|ensureDecoded')"
echo "K11 rows collection-PV $(grep -cE "^  it\('PV[0-9]+ " $TC) stream $(grep -cE "^  it\('PS[0-9]+ " $T) last $(grep -oE "^  it\('PS[0-9]+" $T | tail -1 | cut -c7-) PS27 $(grep -c "it('PS27 " $T) PS28 $(grep -c "it('PS28 " $T) PS29 $(grep -c "it('PS29 " $T)"
echo "K12 perf spec-rows $(grep -cE "'res\.(harness\.preview-stream-playing|mem\.pcm-live-preview-delta-mib|mem\.pcm-live-preview-decode-count)'" $PS) restore $(grep -c '__czabaPreviewRestore' $PS) budgets-rows $(grep -cE '"id": "res\.(harness\.preview-stream-playing|mem\.pcm-live-preview-delta-mib|mem\.pcm-live-preview-decode-count)"' $PB) budgets-total $(grep -c '"id": "res\.' $PB)"
echo "K13 doc252 l4 $(sed -n 4p $D) | l1 $(sed -n 1p $D | grep -oE '\(rounds [^)]*\)') | headings $(grep -c '^## ' $D) | doc248 l4 $(sed -n 4p $D8) | in-progress-docs $(grep -rln 'In Progress (stage' $S/docs/implementation | wc -l)"
echo "K14 SWEEP purchased adapter callers outside tests (roots app/** perf/** e2e/**): $(grep -rlE 'createPurchasedWorkspaceCollection' $S/app $S/perf $S/e2e --include=*.ts --include=*.tsx | grep -v __tests__ | sed "s#$S/##" | sort | tr '\n' ' ')"
echo "K15 SWEEP previewUrl (roots app/** perf/** e2e/**, non-test): $(grep -rlE '\bpreviewUrl\b' $S/app $S/perf $S/e2e --include=*.ts --include=*.tsx | grep -v __tests__ | sed "s#$S/##" | sort | tr '\n' ' ')"
echo "K16 testid toggle $(grep -c 'data-testid="arrangement-library-preview-toggle"' $LP) labels play $(grep -c "previewPlay: 'Preview'," $S/app/lib/arrangement/strings.ts) stop $(grep -c "previewStop: 'Stop'," $S/app/lib/arrangement/strings.ts) demo-url $(grep -c "'demo-middle-east': '/middle-east.mp3'," $S/app/data/studio-lab-demo.ts)"
echo "K17 mutants $(grep -c ' RED ' b-round-395/mutants/summary.txt) red, $(grep -c SURVIVED b-round-395/mutants/summary.txt) survived, $(grep pristine b-round-395/mutants/summary.txt | tr '\n' ' ')"
echo "K18 perf-sketch $(python3 -I -c "import json;r={x['id']:x for x in json.load(open('b-round-395/perf-sketch-latest-resources.json'))['rows']};print(*[(k,r[k]['median'],r[k]['pass']) for k in ['res.harness.preview-stream-playing','res.mem.pcm-live-preview-delta-mib','res.mem.pcm-live-preview-decode-count','res.mem.pcm-live-mib-ready','res.mem.pcm-live-mib-after-add']])") | perf-mutant $(python3 -I -c "import json;r={x['id']:x for x in json.load(open('b-round-395/mutants/perf-MU-396-DEMO-NO-STREAM-latest-resources.json'))['rows']};print(*[(k,r[k]['median'],r[k]['pass']) for k in ['res.harness.preview-stream-playing','res.mem.pcm-live-preview-delta-mib','res.mem.pcm-live-preview-decode-count']])")"
echo "K19 sketch-sha256 $(sha256sum b-round-395/sketch-396.patch.txt | cut -c1-16) applies-to-tree $(cd $S && git apply --check $L/b-round-395/sketch-396.patch.txt 2>/dev/null && echo yes || echo no) review-sha $(grep -c '91c5d73012eeb0b43f61d304f3c8743e1dfcc5beae96d8367b00407eeb7dc50a' b-round-395/sketch-review.md)"
echo "K20 probe R8 $(python3 -I -c "import json;d=json.load(open('b-round-395/probe/rows-R8.json'));print(*[(k,v['crossOrigin'],v['media'][0]['paused'],len(v['dec'])) for k,v in d.items()])") R1b $(python3 -I -c "import json;d=json.load(open('b-round-395/probe/rows-R1b.json'));print(*[(k,v['msAfterSeek'],v['dec'],v['starts']) for k,v in d.items()])")"
echo "K21 covering $(sed 's/\x1b\[[0-9;]*m//g' b-round-395/precheck-covering.log | grep -E 'Test Files|Tests ' | tr -s ' ' | tr '\n' ' ') full $(sed 's/\x1b\[[0-9;]*m//g' b-round-395/precheck-full.log | grep -E 'Test Files|Tests ' | tr -s ' ' | tr '\n' ' ') covering-files $(wc -l < b-round-395/covering-files.txt) LRS4 $(sed 's/\x1b\[[0-9;]*m//g' b-round-395/precheck-covering.log | grep -oE 'LRS4.* [0-9]+ms$' | grep -oE '[0-9]+ms$')"
echo "K22 $(for f in tasks/round-395.md a-round-395.md c-round-395.json c-round-395/rows.mjs c-round-395/warm.mjs c-round-382/lib.mjs b-round-395/grants-396.txt b-round-395/r396-frozen-sha256.txt b-round-318/protected-sha256.txt b-round-395/sketch-396.patch.txt b-round-395/sketch-review.md b-round-395/mutants/summary.txt b-round-395/mutants/run.py b-round-395/mutants/perf-MU-396-DEMO-NO-STREAM.log b-round-395/perf-sketch.log b-round-395/perf-sketch-latest-resources.json b-round-395/precheck-covering.log b-round-395/precheck-full.log b-round-395/covering-files.txt b-round-395/probe/rows.mjs b-round-395/probe/rows-R8.json b-round-395/probe/rows-R1b.json tools/l57-check.py; do test -e $f || echo MISSING:$f; done; echo checked)"
